list_tax_codes.code:
var response = await client.TaxCodes.ListTaxCodesAsync(
    new Dictionary<string, object?> { ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var taxCode in ((IReadOnlyList<object?>)body["tax_codes"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{taxCode["id"]} {taxCode["name"]} {taxCode["rate"]}");

create_tax_code.code:
var response = await client.TaxCodes.CreateTaxCodeAsync(new Dictionary<string, object?>
{
    ["tax_code"] = new Dictionary<string, object?>
    {
        ["name"] = "LUXURY", ["label"] = "Luxury goods", ["description"] = "Higher rate for luxury goods",
        ["rate"] = 15.0, ["resolver_type"] = "flat", ["priority"] = 1,
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var taxCode = (IReadOnlyDictionary<string, object?>)body["tax_code"]!;
Console.WriteLine(taxCode["id"]);

